mapper.select:
SELECT COUNT(1)
FROM conversation
WHERE id = #{conversationId}
  AND user_name = #{userName}

mapper.update:
UPDATE conversation
SET name = #{updateConversationNameDTO.name},
    update_time=#{now}
WHERE id = #{updateConversationNameDTO.conversationId}
  AND user_name = #{userName}

mapper.select:
SELECT m.id, m.conversation_id, m.content, m.role
FROM conversation_message m
INNER JOIN conversation c ON c.id = m.conversation_id
WHERE m.conversation_id = #{conversationId}
  AND c.user_name = #{userName}
ORDER BY m.id ASC

mapper.delete:
DELETE FROM conversation
WHERE id = #{conversationId}
  AND user_name = #{userName}
